contact=intro('Let’s create something lasting','Your space.<br><em>A world of possibilities.</em>','Tell us a little about your outdoor space. A thoughtful landscape starts with understanding what matters to you.','Enquiry')+f'''<section class="wrap enquiry-grid"><aside class="enquiry-aside"><div>{picture('pergola-terrace','Inviting green terrace with pergola and comfortable seating')}</div><h3>A good place to begin.</h3><p>Think about how you want to spend time outdoors, the feeling you want to create, and the details your space needs.</p><div class="contact-fact"><small>Based in</small>Kolkata, West Bengal</div><div class="contact-fact"><small>Our work spans</small>Residential · Commercial · Institutional · Hospitality</div><div class="contact-fact"><small>Helpful to have ready</small>Site photographs, approximate dimensions and your preferred timeline.</div></aside><form class="enquiry-form" id="enquiry-form"><div class="eyebrow">Prepare your project brief</div><div class="form-row"><div class="field"><label for="name">Your name *</label><input id="name" name="name" autocomplete="name" required maxlength="100" placeholder="Full name"></div><div class="field"><label for="location">Project location *</label><input id="location" name="location" required maxlength="150" placeholder="Area / city"></div></div><div class="form-row"><div class="field"><label for="property">Type of space *</label><select id="property" name="property" required><option value="">Select your space</option><option>Residential</option><option>Commercial</option><option>Institutional</option><option>Hospitality</option><option>Other</option></select></div><div class="field"><label for="area">Approximate area</label><input id="area" name="area" maxlength="100" placeholder="e.g. 1,000 sq ft"></div></div><div class="field"><fieldset><legend>What can we help you with? *</legend><div class="choice-list">'''+''.join(f'<label><input type="checkbox" name="services" value="{s[1]}" data-service="{s[0]}"><span>{s[1].replace("Landscape design & development","Landscape design").replace("Gardens, lawns & living greenery","Gardens & greenery").replace("Outdoor living & structures","Outdoor living").replace("Water, stone & finishing details","Water & details").replace("Recreation, irrigation & lasting care","Recreation & care")}</span></label>' for s in services)+'''</div></fieldset><p class="status-message" id="service-error" role="alert"></p></div><div class="form-row"><div class="field"><label for="budget">Your budget range</label><select id="budget" name="budget"><option>To be discussed</option><option>Under ₹1 lakh</option><option>₹1–3 lakh</option><option>₹3–5 lakh</option><option>₹5–10 lakh</option><option>₹10 lakh and above</option></select></div><div class="field"><label for="timeline">When would you like to begin?</label><select id="timeline" name="timeline"><option>Exploring options</option><option>Within a month</option><option>In 1–3 months</option><option>In 3–6 months</option><option>Later this year</option></select></div></div><div class="field"><label for="vision">Tell us about your vision *</label><textarea id="vision" name="vision" required minlength="10" maxlength="3000" placeholder="What would you love your space to become?"></textarea></div><p class="form-note">Create a project brief you can copy or download to share with the team. This form does not send an enquiry, and your details are not stored on the site.</p><button class="button" type="submit">Create my project brief <span class="arrow">↗</span></button><section class="form-result" id="form-result" hidden tabindex="-1"><h3>Your vision, ready to share.</h3><p>Your brief is prepared below. Copy or download it to share with The Gupta’s Landscape. It has not been sent.</p><pre id="brief-preview"></pre><div class="result-actions"><button class="button" id="copy-brief" type="button">Copy brief <span>↗</span></button><button class="button outline" id="download-brief" type="button">Download brief <span>↓</span></button></div><div id="copy-status" class="status-message" role="status"></div></section></form></section>'''
